library IEEE;
use IEEE.STD_LOGIC_1164.ALL;


-- Uncomment the following library declaration if using
-- arithmetic functions with Signed or Unsigned values
use IEEE.NUMERIC_STD.ALL;

-- Uncomment the following library declaration if instantiating
-- any Xilinx leaf cells in this code.
--library UNISIM;
--use UNISIM.VComponents.all;

entity ram is
    Port ( rom_selection : in unsigned (2 downto 0);
           cpu_read_address : in unsigned (11 downto 0);
           cpu_RE : in STD_LOGIC;
           cpu_write_address : in unsigned (11 downto 0);
           cpu_write_data : in unsigned (7 downto 0);
           cpu_WE : in STD_LOGIC;
           CLK : in STD_LOGIC;
           cpu_data_out : out unsigned(7 downto 0);
           cpu_read_ack : out STD_LOGIC;
           --GPU Signals
           gpu_RE : in STD_LOGIC;
           gpu_read_address : in unsigned (11 downto 0);
           gpu_data_out : out unsigned(7 downto 0);
           gpu_read_ack : out STD_LOGIC
           );
end ram;

architecture Behavioral of ram is

type ram_type is array(0 to 32767) of unsigned(7 downto 0);

signal ram_data : ram_type := (
