--    -- ==========================================
--    -- PROGRAM CHIP-8: SPACE INVADER ZBURATOR
--    -- ==========================================
    
--    -- INITIALIZARE
--    16#200# => x"00", 16#201# => x"E0", -- CLS: Curata ecranul
--    16#202# => x"60", 16#203# => x"00", -- LD V0, 0: Coordonata X = 0
----    16#204# => x"61", 16#205# => x"0E", -- LD V1, 14: Coordonata Y = 14
----    16#206# => x"A2", 16#207# => x"20", -- LD I, 0x220: Seteaza I la adresa sprite-ului

--    -- BUCLA DE DESENARE
--    --16#208# => x"D0", 16#209# => x"18", -- DRW V0, V1, 8: Deseneaza sprite de 8 bytes

----    -- DELAY LOOP (Ca sa ai timp sa il vezi, altfel zboara in nanosecunde)
----    -- Folosim doua countere (V3 si V2) pentru o bucla imbricata
----    16#20A# => x"63", 16#20B# => x"10", -- LD V3, 16: Outer loop counter
----    16#20C# => x"62", 16#20D# => x"FF", -- LD V2, 255: Inner loop counter
----    16#20E# => x"72", 16#20F# => x"FF", -- ADD V2, 255 (Aduna -1, scade counter-ul)
----    16#210# => x"32", 16#211# => x"00", -- SE V2, 0: Daca V2 e 0, sari peste urmatoarea
----    16#212# => x"12", 16#213# => x"0E", -- JP 0x20E: Intoarce-te in inner loop
----    16#214# => x"73", 16#215# => x"FF", -- ADD V3, 255 (Scade outer counter-ul)
----    16#216# => x"33", 16#217# => x"00", -- SE V3, 0: Daca V3 e 0, sari peste urmatoarea
----    16#218# => x"12", 16#219# => x"0C", -- JP 0x20C: Reseteaza inner loop si repeta1

----    -- STERGERE SI MISCARE
----    16#21A# => x"D0", 16#21B# => x"18", -- DRW V0, V1, 8: Deseneaza iar (XOR sterge sprite-ul)
----    16#21C# => x"70", 16#21D# => x"01", -- ADD V0, 1: Muta X la dreapta cu 1 pixel
--    16#21E# => x"12", 16#21F# => x"08", -- JP 0x208: Sari inapoi la desenare

--    -- ==========================================
--    -- DATELE SPRITE-ULUI (1 Byte = 8 Pixeli)
