begin

process(CLK)
begin
    if rising_edge(CLK) then
        cpu_read_ack <= '0';
        gpu_read_ack <= '0';
        if gpu_RE = '1' then
            gpu_data_out <= ram_data(to_integer(rom_selection & gpu_read_address));
            gpu_read_ack <= '1';
        end if;
        if cpu_RE = '1' then
            cpu_data_out <= ram_data(to_integer(rom_selection & cpu_read_address));
            cpu_read_ack <= '1';
        end if;
        if cpu_WE = '1' then
            ram_data(to_integer(rom_selection & cpu_write_address)) <= cpu_write_data;
        end if;
    end if;

end process;

end Behavioral;
